import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 77 · ANGLE: stranger returns years later (fed a hungry boy at the diner, he comes back)

sc("""Sweetheart, in the winter of nineteen seventy-two, I was a waitress at the Elm Street Diner, and a skinny boy about twelve years old came in out of the snow every night at closing time and stole the dinner rolls off the dirty plates. My boss wanted to call the police. Instead, I did something that got me fired. And thirty years later, that boy walked back through my door.""",
   "boy in snow outside diner window night", "HE STOLE THE DINNER ROLLS")
sc("""Tonight I'm going to tell you exactly what I did for that boy, why it cost me my job, and what he was holding in his hand when he came back, thirty years later, on Christmas Eve. Stay with me, honey, because I've told this story at every Christmas dinner since, and the grown men in my family still have to leave the room at the end.""",
   "elderly woman telling story by fireplace", "THIRTY YEARS LATER")

ch("The diner")
sc("""The Elm Street Diner was a long silver building with red stools and a jukebox that only played Patsy Cline. I worked the night shift, four to eleven, for a dollar sixty an hour plus tips. My husband Harold was working double shifts at the plant, and we had two little ones at home. Every penny mattered. That job mattered.""",
   "1970s silver diner red stools", "A DOLLAR SIXTY AN HOUR")
sc("""My boss was a man named Earl Pruitt. Earl wasn't a bad man, exactly. He was a tired man, and a tight one. He counted the sugar packets. He made us scrape the butter pats off the plates and reuse them. And he had a rule, posted right over the coffee machine in red marker. No loitering. No credit. No free food. Ever.""",
   "handwritten sign no free food diner", "NO FREE FOOD. EVER.")
sc("""The first time I saw the boy, it was the second week of December. I was bussing a table near the back door, and I turned around, and there he was, a skinny kid in a jacket two sizes too small, stuffing a half-eaten dinner roll in his pocket. He looked at me. I looked at him. And then he ran out that back door into the snow like a rabbit.""",
   "thin boy too small jacket running in snow", "HE RAN LIKE A RABBIT")

ch("The boy")
sc("""He came back the next night. And the next. Always at ten thirty, right at closing, when the plates were piling up. He'd slip in the back, grab whatever was left, and disappear. I started leaving the rolls a little closer to the door. Then a piece of chicken. Then half a hamburger that a trucker hadn't finished. I never said a word, and neither did he.""",
   "plate of leftover food by diner back door", "CLOSER TO THE DOOR")
sc("""One night, about a week in, he didn't run. He stood there by the back door, holding a cold french fry, and he said, very quietly, thank you, ma'am. And I said, what's your name, honey? He said, Danny. Same as my little brother. I asked where his mother was. He looked at the floor and said, she's sick. And I knew exactly what kind of sick he meant.""",
   "boy standing by back door at night", "SHE'S SICK")
sc("""Danny lived with his mother in a room above the pool hall on Third Street. No heat. No food in the icebox. She drank whatever money came into that room, and Danny had been feeding himself out of garbage cans since the summer. He was twelve years old, honey. Twelve. In a minute I'll tell you what he asked me for, and it wasn't food.""",
   "dark room above pool hall winter", "TWELVE YEARS OLD")

ch("The plates")
sc("""After that, I stopped leaving him leftovers. I started making him a real plate. A hamburger, fries, a glass of milk, and a piece of pie, every single night at ten thirty. I paid for it out of my tips, sweetheart. Every penny, written down on a ticket and paid at the register, so nobody could ever say I stole it. It came to about a dollar ten a night.""",
   "hamburger plate and milk on diner counter", "A REAL PLATE")
sc("""If you're enjoying Grandma's story, tap the like button for me, honey. It helps more people find these stories. Danny would sit on an upside-down milk crate in the back hallway and eat every crumb. And then he'd do his homework there, at the little shelf by the mop sink, while I closed up. He was smart, sweetheart. Sharp as a tack. He wanted to know how everything worked.""",
   "boy doing homework in back hallway", "SHARP AS A TACK")
sc("""One night he asked me the thing I promised you. He didn't ask for money, or a coat, or anything to eat. He asked me if I had any books at home. Any books at all. He said the library in town made you have a parent sign the card, and his mother couldn't get out of bed. So I brought him my Harold's old encyclopedias, one volume at a time.""",
   "old encyclopedia volumes stack", "ANY BOOKS AT ALL")

ch("Fired")
sc("""On the twenty-third of December, Earl came back early from his brother's house. He walked in the back door at ten forty and found a twelve-year-old boy on a milk crate, eating pie and reading volume M of the encyclopedia. Earl's face turned purple. He said, what is this? I told you. No loitering, no free food, ever. Get that kid out of here.""",
   "angry diner owner in doorway", "WHAT IS THIS?")
sc("""I showed him the tickets. Every single one, paid with my own money. Earl didn't care. He said, I don't run a charity. That kid's mother is a drunk, and he's a thief, and he'll be in jail by sixteen. And if you feed him again, you're done. Danny was standing right there, sweetheart. He heard every word. I saw his face close up like a fist.""",
   "boy hearing cruel words face hurt", "JAIL BY SIXTEEN")
sc("""I took off my apron. I folded it up nice and neat, and I laid it on the counter, and I said, Earl, then I'm done. And I took Danny by the hand, and I walked him out that back door into the snow, two days before Christmas, with no job and two babies at home. Harold was going to kill me. I knew it the whole walk home.""",
   "waitress apron folded on counter", "THEN I'M DONE")

ch("Christmas")
sc("""Harold didn't kill me, honey. When I told him, he sat quiet for a minute, and then he said, Ruthie, where's the boy sleeping tonight? And that's how Danny came to spend Christmas of nineteen seventy-two on the couch in our living room. My mother came over and cut his hair. Harold gave him his old winter coat. And on Christmas morning, there was a present under our tree with his name on it.""",
   "boy asleep on couch Christmas tree 1970s", "WHERE'S THE BOY SLEEPING?")
sc("""It was a library card, sweetheart. Harold had gone down to the library on Christmas Eve and signed it himself, as his guardian, and he'd wrapped it in the funny papers. Danny opened that box and looked at that little card, and he cried so hard he couldn't breathe. A library card. Of all the presents I've ever seen opened, that's the one I remember.""",
   "library card in small gift box", "A LIBRARY CARD")
sc("""After New Year's, the county stepped in. Danny's mother went to a hospital in Columbus, and Danny went to live with an aunt in Cleveland. We put him on a Greyhound bus with a sack lunch, the encyclopedias in a cardboard box, and our address on a piece of paper in his pocket. He waved out the back window until the bus turned the corner. And then I didn't hear from him for thirty years.""",
   "boy waving from back window of bus", "THIRTY YEARS OF SILENCE")

ch("Thirty years")
sc("""So far, the rolls, the plates, the books, and the bus. Life went on, honey. I found another job at the five-and-dime. Our children grew up. Harold retired. And every Christmas, I'd wonder about that skinny boy. Did he make it? Was Earl right? Was he in jail somewhere? I'd pray for him at the Christmas Eve service, every single year, and I never told anybody why.""",
   "woman praying in church candlelight", "WAS EARL RIGHT?")
sc("""On Christmas Eve, two thousand two, there was a knock on our door at six o'clock. Harold opened it, and there stood a tall man in a camel coat, maybe forty, with a little girl holding his hand. He said, excuse me, sir. Does Ruth Miller still live here? Harold said, who's asking? And the man said, tell her it's Danny. Tell her I brought back volume M.""",
   "tall man in camel coat at front door snow", "I BROUGHT BACK VOLUME M")

ch("Who he became")
sc("""I came to the door, honey, and I knew him in one second. The same eyes. He was holding that old encyclopedia under his arm, volume M, with my Harold's name still written inside the cover. He said, I've carried this with me through two colleges, four apartments, and three states. I figured it was time to return it. And then that big grown man hugged me and wouldn't let go.""",
   "man hugging elderly woman at door", "THROUGH TWO COLLEGES")
sc("""Danny was Dr. Daniel Hayes now. A pediatrician, sweetheart. A children's doctor in Cleveland, with his own practice. The little girl was his daughter, Ruthie. He'd named her after me. He said, I always told her that a waitress in Mansfield saved my life with a hamburger and a library card, and she wanted to meet you. I sat down right on the stairs, because my knees gave out.""",
   "doctor with little daughter smiling", "HE NAMED HER RUTHIE")
sc("""And then he handed me an envelope. Inside was a newspaper clipping from the Cleveland paper. It said that Dr. Hayes's clinic had started a program called Ruth's Table, a free hot meal every night at the clinic for any child in the neighborhood who came in hungry. No questions. No forms. No parent signature required. Eleven thousand meals that year, honey. Eleven thousand.""",
   "children eating free meal at clinic", "RUTH'S TABLE")

ch("Earl")
sc("""And there's one more thing, the part people never believe. Danny asked me, is Earl Pruitt still alive? He was. Eighty-one years old, in a nursing home on the east side. So the day after Christmas, Danny drove over there, by himself. He never told me everything they said. But Earl's daughter told me later that her father cried for an hour after that visit.""",
   "elderly man in nursing home chair", "IS EARL STILL ALIVE?")
sc("""Danny told Earl who he was. The thief on the milk crate. The boy who'd be in jail by sixteen. And then he told Earl that he'd examined over forty thousand children in his career, and every single time he saw a hungry one, he thought about that night in the diner, and he decided to be Ruth, and not Earl. Then he shook his hand, and he wished him a merry Christmas.""",
   "two men shaking hands nursing home", "BE RUTH, NOT EARL")

ch("Grandma's lesson")
sc("""Danny and his family come every Christmas Eve now, honey, even since Harold passed. Ruthie is in medical school herself. And every year, Danny brings a new encyclopedia volume to put on my shelf. He's up to volume S. He says when he gets to Z, he'll have paid me back. I tell him he paid me back the day he walked through that door alive.""",
   "encyclopedia volumes on shelf Christmas", "UP TO VOLUME S")
sc("""Here's what I want you to remember, sweetheart. Earl looked at that boy and saw a thief. I looked at him and saw a hungry child. It's the same boy. You get to decide which one you see. And whichever one you see, that's the one you help them become. A dollar ten a night, honey. That's all it cost me. Best money I ever spent.""",
   "diner booth Christmas lights night", "WHICH ONE DO YOU SEE?")
sc("""Tell me in the comments, honey. Would you have quit that job? Be honest with Grandma. And if a stranger ever changed your life, I want to hear about it. There are more of my family's stories in the playlist right there on your screen, and I'll see you in the next one. Good night, sweetheart. Merry Christmas.""",
   "warm diner window snowy night", "WOULD YOU HAVE QUIT?")

for s in S:
    s["cuts"], s["moves"] = 4, True

